properties.query:
SELECT * FROM ${prefix}fs_tickets WHERE id > ${max_id}
AND status = 'closed'
ORDER BY id ASC
LIMIT 0, ${limit}

SELECT * FROM ${prefix}fs_conversations 
WHERE ticket_id = ${ticket_id}
AND conversation_type = 'response'
AND person_id != ${customer_id}
ORDER BY id DESC

